UPDATE businesses SET sections_config='[{"key":"header","on":1,"order":1},{"key":"actions","on":1,"order":2},{"key":"menu","on":1,"order":3},{"key":"about","on":1,"order":4},{"key":"stats","on":1,"order":5},{"key":"gallery","on":1,"order":6},{"key":"services","on":1,"order":7},{"key":"reviews","on":1,"order":8},{"key":"contact","on":1,"order":9},{"key":"clients","on":1,"order":10},{"key":"store","on":1,"order":11},{"key":"creator","on":1,"order":12},{"key":"doctors","on":1,"order":13},{"key":"courses","on":1,"order":14}]' WHERE category_id IN (@cat_rest, @cat_cafe, @cat_ff) AND (sections_config IS NULL OR sections_config='');
